import {get_string as getString} from 'core/str';

/**
 * Represents a button to toggle behavior.
 *
 * @author     Konrad Ebel <konrad.ebel@oncampus.de>
 * @copyright  2025, onCampus GmbH
 */

export class EffectToggleButton {
    constructor(
        buttonElement,
        enableCallback,
        disableCallback,
        disableText,
        enableText,
        isActive = false
    ) {
        this.buttonElement = buttonElement;
        this.disableText = disableText;
        this.enableText = enableText;
        this.isActive = isActive;
        this.enableCallback = enableCallback;
        this.disableCallback = disableCallback;
    }

    initializeCallbacks() {
        if (this.isActive) {
            this.enable();
        } else {
            this.disable();
        }

        this.buttonElement.addEventListener('click', (e) => {
            e.preventDefault();
            if (this.isActive) {
                this.disable();
            } else {
                this.enable();
            }
        });
    }

    /**
     * Enable the button
     */
    enable() {
        this.isActive = true;
        this.updateText();
        this.enableCallback();
    }

    /**
     * Disable the button
     */
    disable() {
        this.isActive = false;
        this.updateText();
        this.disableCallback();
    }

    /**
     * Asynchronously loads the enable/disable language strings for toggling snowfall.
     *
     * @returns {Promise<EffectToggleButton>}
     */
    static async createAnimationToggleButton(active, enableCallback, disableCallback) {
        const toggleBtn = document.getElementById('snowfall-toggle-btn');
        if (!toggleBtn) {
            throw new Error("snowfall-toggle-btn identifier not found");
        }

        const disableText = await getString('disable_snowfall', 'local_oc_seasonal_animations');
        const enableText = await getString('enable_snowfall', 'local_oc_seasonal_animations');
        return new EffectToggleButton(toggleBtn, enableCallback, disableCallback, disableText, enableText, active);
    }

    /**
     * Sets the text content of the toggle button based on the active state.
     */
    updateText() {
        if (this.isActive) {
            this.buttonElement.textContent = this.disable;
        } else {
            this.buttonElement.textContent = this.enable;
        }
    }
}
